INSERT INTO tr_procedures (id, name, application_method, authentication_level, procedure_group, description, search_text, image_url, category_id, institution_id, appointment_required, is_free, cost_amount, cost_currency, cost_comments, validity_value, validity_unit, validity_comments, estimated_delivery_time, view_count, slug_es, slug_en, display_order, created_at, updated_at) VALUES
    ('cccccccc-cccc-4ccc-8ccc-000000000001', 'Cédula de identidad', 'IN_PERSON', 'PUBLIC', 'IDENTITY', 'Documento de identificación obligatorio para ciudadanos y residentes en Uruguay. Se tramita con hora previa en cualquier oficina de la DNIC del país.', 'cedula de identidad documento de identificacion obligatorio para ciudadanos y residentes en uruguay. se tramita con hora previa en cualquier oficina de la dnic del pais.', 'https://picsum.photos/seed/cedula/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000001', TRUE, TRUE, NULL, NULL, NULL, '10', 'años', 'Para menores de 18 años la vigencia es de 5 años.', '10 días hábiles', 18450, 'cedula-de-identidad', 'identity-card', 1, '2024-02-01T09:00:00.000Z', '2025-09-02T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000002', 'Pasaporte uruguayo', 'IN_PERSON', 'PUBLIC', 'DOCUMENTS', 'Documento de viaje emitido por la DNIC. Requiere hora previa y el pago de una tasa vigente al momento del trámite.', 'pasaporte uruguayo documento de viaje emitido por la dnic. requiere hora previa y el pago de una tasa vigente al momento del tramite.', 'https://picsum.photos/seed/pasaporte/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000001', TRUE, FALSE, 3340, 'UYU', 'El valor de la tasa se actualiza periódicamente.', '10', 'años', NULL, '5 a 10 días hábiles', 15230, 'pasaporte', 'passport', 2, '2024-02-01T09:00:00.000Z', '2025-08-15T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000003', 'Partida de nacimiento', 'HYBRID', 'LOCAL_REGISTRATION', 'IDENTITY', 'Certificado oficial del Registro Civil que acredita el nacimiento. Se puede solicitar en línea y retirar o recibir por correo.', 'partida de nacimiento certificado oficial del registro civil que acredita el nacimiento. se puede solicitar en linea y retirar o recibir por correo.', 'https://picsum.photos/seed/partida/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000001', FALSE, TRUE, NULL, NULL, NULL, '6', 'meses', 'Los organismos suelen exigir ejemplares emitidos dentro de ese plazo.', '5 días hábiles', 9740, 'partida-de-nacimiento', 'birth-certificate', 3, '2024-02-01T09:00:00.000Z', '2025-07-20T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000004', 'Certificado de antecedentes penales', 'FULLY_DIGITAL', 'BASIC_DIGITAL_ID', 'DOCUMENTS', 'Certificado que acredita la ausencia de antecedentes penales. Se emite al instante en formato digital con identidad gub.uy.', 'certificado de antecedentes penales certificado que acredita la ausencia de antecedentes penales. se emite al instante en formato digital con identidad gub.uy.', 'https://picsum.photos/seed/antecedentes/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000008', FALSE, TRUE, NULL, NULL, NULL, '6', 'meses', NULL, 'Inmediata (PDF)', 12860, 'antecedentes-penales', 'criminal-record-certificate', 4, '2024-02-01T09:00:00.000Z', '2025-06-10T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000005', 'Certificado de residencia', 'HYBRID', 'PUBLIC', 'IDENTITY', 'Documento municipal que acredita el domicilio declarado. Se solicita en línea o con hora previa en tu municipio.', 'certificado de residencia documento municipal que acredita el domicilio declarado. se solicita en linea o con hora previa en tu municipio.', 'https://picsum.photos/seed/residencia/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000003', FALSE, TRUE, NULL, NULL, NULL, '1', 'año', 'Algunos municipios exigen emisión reciente de hasta 3 meses.', '3 días hábiles', 8120, 'certificado-de-residencia', 'residence-certificate', 5, '2024-02-01T09:00:00.000Z', '2025-05-30T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000006', 'Apostilla de documentos', 'FULLY_DIGITAL', 'LOCAL_REGISTRATION', 'DOCUMENTS', 'Legalización internacional de documentos uruguayos para ser usados en el exterior. Se solicita en línea y se entrega apostillada.', 'apostilla de documentos legalizacion internacional de documentos uruguayos para ser usados en el exterior. se solicita en linea y se entrega apostillada.', 'https://picsum.photos/seed/apostilla/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000001', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000002', FALSE, FALSE, 2150, 'UYU', 'El costo depende de la cantidad de documentos.', NULL, NULL, NULL, '5 días hábiles', 6930, 'apostilla-de-documentos', 'document-apostille', 6, '2024-02-01T09:00:00.000Z', '2025-04-18T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000007', 'Licencia de conducir', 'HYBRID', 'PUBLIC', 'VEHICLES', 'Habilitación para conducir vehículos en todo el territorio nacional. Incluye examen teórico y práctico según la categoría.', 'licencia de conducir habilitacion para conducir vehiculos en todo el territorio nacional. incluye examen teorico y practico segun la categoria.', 'https://picsum.photos/seed/licencia/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000002', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000004', TRUE, FALSE, 1980, 'UYU', 'El valor varía según la categoría y la intendencia.', '10', 'años', 'Vigencia reducida para mayores de 65 años.', '10 días hábiles', 22140, 'licencia-de-conducir', 'drivers-license', 7, '2024-02-01T09:00:00.000Z', '2025-09-25T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000008', 'Matrícula de vehículo', 'FULLY_DIGITAL', 'BASIC_DIGITAL_ID', 'VEHICLES', 'Alta y renovación anual de la matrícula del vehículo mediante el sistema Sucive. Incluye el pago del tributo anual.', 'matricula de vehiculo alta y renovacion anual de la matricula del vehiculo mediante el sistema sucive. incluye el pago del tributo anual.', 'https://picsum.photos/seed/matricula/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000002', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000003', FALSE, FALSE, 3420, 'UYU', 'El monto se calcula según la tasación del vehículo.', '1', 'año', NULL, 'Inmediata', 14560, 'matricula-de-vehiculo', 'vehicle-registration', 8, '2024-02-01T09:00:00.000Z', '2025-01-22T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000009', 'Transferencia de vehículo', 'HYBRID', 'BASIC_DIGITAL_ID', 'VEHICLES', 'Cambio de titularidad de un vehículo empadronado en Uruguay. Se inicia en línea y finaliza con la firma y verificación de la intendencia.', 'transferencia de vehiculo cambio de titularidad de un vehiculo empadronado en uruguay. se inicia en linea y finaliza con la firma y verificacion de la intendencia.', 'https://picsum.photos/seed/transferencia/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000002', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000003', TRUE, FALSE, 5460, 'UYU', 'Incluye tasas municipales y el formulario de transferencia.', NULL, NULL, NULL, '2 días hábiles', 7380, 'transferencia-de-vehiculo', 'vehicle-transfer', 9, '2024-02-01T09:00:00.000Z', '2025-08-05T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000010', 'Carné de salud', 'IN_PERSON', 'PUBLIC', 'HEALTH', 'Certificado de aptitud física exigido para trabajar, estudiar o tramitar la licencia de conducir. Se emite en centros habilitados por el MSP.', 'carne de salud certificado de aptitud fisica exigido para trabajar, estudiar o tramitar la licencia de conducir. se emite en centros habilitados por el msp.', 'https://picsum.photos/seed/carne-salud/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000003', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000005', TRUE, FALSE, 890, 'UYU', 'Puede ser gratuito según el prestador de salud.', '1', 'año', 'Seis meses para algunas actividades específicas.', 'En el momento', 16820, 'carne-de-salud', 'health-card', 10, '2024-02-01T09:00:00.000Z', '2025-07-15T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000011', 'Historia laboral', 'FULLY_DIGITAL', 'BASIC_DIGITAL_ID', 'WORK', 'Constancia de todos los aportes registrados en el BPS. Indispensable para jubilaciones, pensiones y verificación de años trabajados.', 'historia laboral constancia de todos los aportes registrados en el bps. indispensable para jubilaciones, pensiones y verificacion de anos trabajados.', 'https://picsum.photos/seed/historia-laboral/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000004', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000006', FALSE, TRUE, NULL, NULL, NULL, '3', 'meses', 'Muchos organismos exigen emisión reciente.', 'Inmediata (PDF)', 11230, 'historia-laboral', 'employment-history', 11, '2024-02-01T09:00:00.000Z', '2025-06-22T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000012', 'Constancia de situación tributaria', 'FULLY_DIGITAL', 'BASIC_DIGITAL_ID', 'TAXES', 'Documento emitido por la DGI que certifica tu situación fiscal. Se genera al instante desde los servicios en línea.', 'constancia de situacion tributaria documento emitido por la dgi que certifica tu situacion fiscal. se genera al instante desde los servicios en linea.', 'https://picsum.photos/seed/constancia-dgi/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000005', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000007', FALSE, TRUE, NULL, NULL, NULL, '30', 'días', NULL, 'Inmediata (PDF)', 6420, 'constancia-tributaria', 'tax-standing-certificate', 12, '2024-02-01T09:00:00.000Z', '2025-05-12T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000013', 'Título profesional', 'HYBRID', 'LOCAL_REGISTRATION', 'EDUCATION', 'Expedición de título o certificado de egreso de carreras de la Universidad de la República. Se solicita en línea y se retira firmado.', 'titulo profesional expedicion de titulo o certificado de egreso de carreras de la universidad de la republica. se solicita en linea y se retira firmado.', 'https://picsum.photos/seed/titulo/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000006', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000009', FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, '15 días hábiles', 5210, 'titulo-profesional', 'professional-degree', 13, '2024-02-01T09:00:00.000Z', '2025-03-08T10:00:00.000Z'),
    ('cccccccc-cccc-4ccc-8ccc-000000000014', 'Permiso de construcción', 'HYBRID', 'LOCAL_REGISTRATION', 'HOUSING', 'Autorización municipal para construir, ampliar o refaccionar una vivienda. Requiere proyecto de arquitecto y revisión técnica.', 'permiso de construccion autorizacion municipal para construir, ampliar o refaccionar una vivienda. requiere proyecto de arquitecto y revision tecnica.', 'https://picsum.photos/seed/construccion/800/500', 'aaaaaaaa-aaaa-4aaa-8aaa-000000000007', 'bbbbbbbb-bbbb-4bbb-8bbb-000000000003', FALSE, FALSE, 11800, 'UYU', 'La tasa se calcula según metros cuadrados y tipo de obra.', NULL, NULL, NULL, '30 días hábiles', 3890, 'permiso-de-construccion', 'construction-permit', 14, '2024-02-01T09:00:00.000Z', '2025-10-01T10:00:00.000Z');
